using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;
namespace NcnHelper {
public static class Connection {
 public static Plan Build(string game){Core.ValidateRoot(game);string file=Core.Config(game);string original=File.ReadAllText(file);var cfg=Json.Read(original);var llm=Json.Obj(cfg,"llm");foreach(string key in new[]{"api_url","api_key","model"})if(!llm.ContainsKey(key))throw new Exception("Unknown LLM structure: missing field "+key);var edits=new Dictionary<string,object>{{"/llm/api_url","http://127.0.0.1:17862/v1"},{"/llm/api_key",""},{"/llm/model","nightcitynet-local"}};if(llm.ContainsKey("timeout_sec"))edits["/llm/timeout_sec"]=180;foreach(var kv in llm){if(kv.Key.StartsWith("_")){if(Convert.ToString(kv.Value).IndexOf("openrouter",StringComparison.OrdinalIgnoreCase)>=0)edits["/llm/"+kv.Key]="Local LLM connection managed by NightCityNet Helper. Previous settings are in the private rollback backup.";continue;}if(kv.Key.EndsWith("_model"))edits["/llm/"+kv.Key]="nightcitynet-local";if(kv.Key=="provider")edits["/llm/provider"]=new Dictionary<string,object>();if(kv.Key.EndsWith("request_overrides")&&kv.Value is Dictionary<string,object>){var keep=new Dictionary<string,object>((Dictionary<string,object>)kv.Value);keep.Remove("provider");keep.Remove("model");edits["/llm/"+kv.Key]=keep;}}var p=new Plan{Game=Path.GetFullPath(game)};Core.Add(p,file,Core.Encode(JsonPatch.Apply(original,edits),file),null);string runtime=Path.Combine(Core.Mod(game),@"data\stt\OpenRouter.yaml");if(File.Exists(runtime)){string t=File.ReadAllText(runtime);if(Regex.Matches(t,@"(?m)^  timeout:[^\r\n]*").Count==1){string updated=Regex.Replace(t,@"(?m)^  timeout:[^\r\n]*","  timeout: 180");Core.Add(p,runtime,Core.Encode(updated,runtime),null);}}p.Summary.Add("LLM and background jobs use local model nightcitynet-local. TTS, Whisper and memory are preserved.");return p;}
}
}
